import { NetworkEnvironment, TxIn } from "@repo/ledger-core";
import { RustModule } from "@repo/ledger-utils";
import { beforeAll, describe, expect, it } from "vitest";
import * as S from "../src";

beforeAll(async () => {
  await RustModule.load();
});

describe("Transaction.fromECSL", () => {
  it("should parse transaction inputs, outputs, referenceInputs, and mint", () => {
    const ECSL = RustModule.getE;
    const txRaw =
      "";
    const eTx = ECSL.Transaction.from_hex(txRaw);

    const tx = S.Transaction.fromECSL(eTx);

    // Verify inputs
    expect(tx.body.inputs).toHaveLength(3);
    expect(TxIn.toString(tx.body.inputs[0])).toBe(
      "35753ae6089deb73d6835315296f3afe17ff3718df50937082d246a48ff3cb09#7",
    );
    expect(TxIn.toString(tx.body.inputs[1])).toBe(
      "935d13db45df377b7235a4ad358da539be0180b81f1f856365e87cba55670e10#0",
    );
    expect(TxIn.toString(tx.body.inputs[2])).toBe(
      "d685fc8f3174fb8b25f195ed9ae2e2da8765afe0816224f24a9e4394f6935eed#0",
    );

    // Verify outputs
    expect(tx.body.outputs).toHaveLength(3);

    // Verify reference inputs
    expect(tx.body.referenceInputs).toHaveLength(2);
    expect(TxIn.toString(tx.body.referenceInputs[0])).toBe(
      "5ec56338104fcbfe32288c649d9633f0d9060abce8b8608b156294f0a81d29e2#1",
    );
    expect(TxIn.toString(tx.body.referenceInputs[1])).toBe(
      "babc647257b8d78b86e862ba9769401714ed403e7c46ed1b59c3fc32e0247c82#0",
    );

    expect(tx.body.mint.flatten()).toHaveLength(0);
  });

  it("create pool tx", () => {
    const rawTx =
      "";
    const ECSL = RustModule.getE;
    const eTx = ECSL.Transaction.from_hex(rawTx);
    const tx = S.Transaction.fromECSL(eTx);
    const minswapV2Tx = S.MinswapV2Syncer.parseTx({
      tx,
      networkEnv: NetworkEnvironment.TESTNET_PREPROD,
      mapPool: {},
    });
    expect(minswapV2Tx?.type).toBe(S.MinswapV2Syncer.TxType.CREATE_POOL);
  });

  it("minswap v1 | create order", () => {
    const txRaw =
      "";
    const ECSL = RustModule.getE;
    const eTx = ECSL.Transaction.from_hex(txRaw);
    const tx = S.Transaction.fromECSL(eTx);
    expect(
      tx.witnessSet.plutusData[
        "94b44c57b5fd8a60c363a6ce0bddceb6258d59cca55b733f59203a55a3d037ab"
      ].hex,
    ).toEqual(
      "",
    );
    const minswapV1Tx = S.MinswapV1Syncer.parseTx({
      tx,
      networkEnv: NetworkEnvironment.TESTNET_PREPROD,
    });
    expect(minswapV1Tx?.type).toBe(S.MinswapV1Syncer.TxType.CREATE_ORDER);
  });

  it("sundaeswap v1 | create order", () => {
    const txRaw =
      "";
    const ECSL = RustModule.getE;
    const eTx = ECSL.Transaction.from_hex(txRaw);
    const tx = S.Transaction.fromECSL(eTx);
    const sundaeswapV1Tx = S.SundaeSwapV1Syncer.parseTx({
      tx,
      mapPool: {
        b003: {
          assetA: "lovelace",
          assetB:
            "533bb94a8850ee3ccbe483106489399112b74c905342cb1792a797a0.494e4459",
        },
      },
      networkEnv: NetworkEnvironment.MAINNET,
    });
    expect(sundaeswapV1Tx?.type).toBe(S.SundaeSwapV1Syncer.TxType.CREATE_ORDER);
  });

  it("sundaeswap v1 | create pool", () => {
    const txRaw = "";
    const ECSL = RustModule.getE;
    const eTx = ECSL.Transaction.from_hex(txRaw);
    const tx = S.Transaction.fromECSL(eTx);
    const sundaeswapV1Tx = S.SundaeSwapV1Syncer.parseTx({
      tx,
      mapPool: {
        b003: {
          assetA: "lovelace",
          assetB:
            "533bb94a8850ee3ccbe483106489399112b74c905342cb1792a797a0.494e4459",
        },
      },
      networkEnv: NetworkEnvironment.MAINNET,
    });
    // console.log(JSON.stringify(sundaeswapV1Tx, null, 2));
    expect(sundaeswapV1Tx?.type).toBe(S.SundaeSwapV1Syncer.TxType.CREATE_POOL);
  });

  it("sundaeswap v3 | create pool", () => {
    const txRaw = "";
    const ECSL = RustModule.getE;
    const eTx = ECSL.Transaction.from_hex(txRaw);
    const tx = S.Transaction.fromECSL(eTx);
    const sundaeswapV3Tx = S.SundaeSwapV3Syncer.parseTx({
      tx,
      mapPool: {},
      networkEnv: NetworkEnvironment.MAINNET,
    });
    // console.log(JSON.stringify(sundaeswapV3Tx, null, 2));
    expect(sundaeswapV3Tx?.type).toBe(S.SundaeSwapV3Syncer.TxType.CREATE_POOL);
  });

  it("sundaeswap v3 | swap", () => {
    // 0ae51905fab9f9fee4f60b5240854a6137386821a643edbe235dbd6717829bdc
    const txRaw = "";
    const ECSL = RustModule.getE;
    const eTx = ECSL.Transaction.from_hex(txRaw);
    const tx = S.Transaction.fromECSL(eTx);
    const sundaeswapV3Tx = S.SundaeSwapV3Syncer.parseTx({
      tx,
      mapPool: {
        ["45d34e72510265588c6a2d5e9aa4c6fb32be16a79ef9846162acdfcb"]: {
          assetA: "lovelace",
          assetB:
            "e992ef75f2367e6ecd93716ae88eba0d005dd91fd3a21f650b6496b5.5355524745",
        },
      },
      networkEnv: NetworkEnvironment.MAINNET,
    });
    // console.log(JSON.stringify(sundaeswapV3Tx, null, 2));
    expect(sundaeswapV3Tx?.type).toBe(S.SundaeSwapV3Syncer.TxType.CREATE_ORDER);
  });
});
